<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Panduan & Petunjuk Penggunaan - Breskul</title>
<script src="https://cdn.tailwindcss.com/3.4.17"></script>
<script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.14.8/dist/cdn.min.js"></script>
<style>
[x-cloak]{display:none !important}
.scrollbar-none{scrollbar-width:none}
.scrollbar-none::-webkit-scrollbar{display:none}
</style>
</head>
<body class="bg-gray-100 text-gray-800" style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif">

<header class="bg-green-800 text-white">
  <div class="max-w-6xl mx-auto px-4 py-3 font-bold tracking-wide">BRESKUL</div>
</header>

<main class="max-w-6xl mx-auto px-4 py-6">
<div class="space-y-6" x-data="panduanApp()" x-cloak>

    <!-- Banner Header -->
    <div class="bg-gradient-to-r from-green-700 via-green-600 to-emerald-600 rounded-2xl shadow-lg p-6 sm:p-8 text-white relative overflow-hidden">
        <div class="relative z-10 max-w-3xl">
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/20 text-xs font-semibold uppercase tracking-wider mb-3">Pusat Bantuan & Edukasi</div>
            <h1 class="text-2xl sm:text-4xl font-extrabold tracking-tight">Panduan Penggunaan Breskul</h1>
            <p class="mt-2 text-green-100 text-sm sm:text-base leading-relaxed">
                Temukan petunjuk lengkap penggunaan aplikasi Breskul (Web & Mobile Service) untuk mengelola data akademik, absensi RFID/QR Code, keuangan, serta pelaksanaan ujian online.
            </p>
            <div class="mt-5 relative">
                <input type="text" x-model="searchQuery" placeholder="Cari topik panduan (contoh: absensi, topup, ujian, password)..."
                    class="w-full pl-11 pr-4 py-3 rounded-xl bg-white text-gray-800 placeholder-gray-400 shadow-md focus:outline-none focus:ring-2 focus:ring-green-400 text-sm sm:text-base" />
                <div class="absolute left-3.5 top-3.5 text-gray-400">
                    <svg xmlns="http://www.w3.org/2000/svg" class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                </div>
            </div>
        </div>
    </div>

    <!-- Tabs Navigation Bar with Scroll & Move Controls -->
    <div class="space-y-2">
        <div class="relative flex items-center bg-white p-1.5 rounded-2xl shadow-sm border border-gray-200">
            <!-- Button Geser Kiri -->
            <button type="button" @click="scrollTabs('left')" title="Geser daftar tab ke kiri"
                class="flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center text-gray-500 hover:text-gray-900 hover:bg-gray-100 transition border border-gray-200/80 bg-white shadow-xs cursor-pointer">
                <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7" />
                </svg>
            </button>

            <!-- Scrollable Tabs List -->
            <div x-ref="tabContainer" class="flex items-center gap-2 overflow-x-auto scroll-smooth scrollbar-none px-2 py-1 flex-1">
                <template x-for="tab in tabs" :key="tab.id">
                    <button type="button" :id="'tab-btn-' + tab.id" @click="goToTab(tab.id)"
                        :class="activeTab === tab.id ? 'bg-green-600 text-white shadow-sm font-semibold' : 'bg-gray-50 text-gray-600 hover:bg-gray-100 hover:text-gray-900 border border-gray-200 font-medium'"
                        class="px-4 py-2 rounded-xl text-xs sm:text-sm whitespace-nowrap transition-all duration-150 flex items-center gap-2 cursor-pointer flex-shrink-0">
                        <span x-text="tab.icon"></span>
                        <span x-text="tab.label"></span>
                    </button>
                </template>
            </div>

            <!-- Button Geser Kanan -->
            <button type="button" @click="scrollTabs('right')" title="Geser daftar tab ke kanan"
                class="flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center text-gray-500 hover:text-gray-900 hover:bg-gray-100 transition border border-gray-200/80 bg-white shadow-xs cursor-pointer">
                <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7" />
                </svg>
            </button>
        </div>

        <!-- Quick Switch Sub-Bar: Pindah Tab Sebelumnya & Selanjutnya -->
        <div class="flex items-center justify-between px-1 text-xs text-gray-500">
            <button type="button" @click="prevTab()" :disabled="!getPrevTab()"
                class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 font-medium shadow-xs transition disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">
                <svg xmlns="http://www.w3.org/2000/svg" class="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" />
                </svg>
                <span>Sebelumnya <span x-show="getPrevTab()" class="hidden md:inline text-gray-500">(<span x-text="getPrevTab() ? getPrevTab().label : ''"></span>)</span></span>
            </button>

            <span class="text-[11px] font-medium text-gray-400">
                Tab <span class="font-bold text-gray-700" x-text="getCurrentTabIndex() + 1"></span> / <span x-text="tabs.length"></span>: <span class="text-green-700 font-semibold" x-text="tabs[getCurrentTabIndex()] ? tabs[getCurrentTabIndex()].label : ''"></span>
            </span>

            <button type="button" @click="nextTab()" :disabled="!getNextTab()"
                class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 text-gray-700 font-medium shadow-xs transition disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">
                <span>Selanjutnya <span x-show="getNextTab()" class="hidden md:inline text-gray-500">(<span x-text="getNextTab() ? getNextTab().label : ''"></span>)</span></span>
                <svg xmlns="http://www.w3.org/2000/svg" class="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7" />
                </svg>
            </button>
        </div>
    </div>

    <div class="space-y-6">

        <!-- TAB 1: PENGENALAN -->
        <div x-show="activeTab === 'overview' && matchesSearch('pengenalan overview sistem role login')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Tentang Aplikasi Breskul</h2>
                <p class="text-xs sm:text-sm text-gray-500">Sistem Informasi Manajemen Sekolah / Perguruan Tinggi Berbasis Cloud & Mobile</p>
            </div>
            <div class="text-gray-600 text-sm leading-relaxed space-y-4">
                <p><strong>Breskul</strong> adalah ekosistem aplikasi terpadu yang dirancang untuk memudahkan operasional sekolah maupun kampus. Sistem ini mencakup aplikasi Manajemen Web untuk Pengelola/Admin dan Guru/Dosen, serta Aplikasi Mobile Flutter (<strong>breskul_app</strong>) untuk Siswa/Mahasiswa dan Orang Tua.</p>
                <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pt-2">
                    <div class="border border-green-200 bg-green-50/50 rounded-xl p-4"><div class="font-semibold text-green-800 text-sm">Super Admin (Role 0)</div><p class="text-xs text-gray-600 mt-1">Mengelola tenant/aplikasi institusi, API Keys, dan referensi Master Jabatan utama.</p></div>
                    <div class="border border-blue-200 bg-blue-50/50 rounded-xl p-4"><div class="font-semibold text-blue-800 text-sm">Admin App (Role 1)</div><p class="text-xs text-gray-600 mt-1">Mengelola seluruh data master instansi (Siswa, Guru, Karyawan, Pembayaran, Kas, Jadwal).</p></div>
                    <div class="border border-purple-200 bg-purple-50/50 rounded-xl p-4"><div class="font-semibold text-purple-800 text-sm">Guru / Dosen (Role 3)</div><p class="text-xs text-gray-600 mt-1">Mengelola bank soal, membuat ujian online, memantau absensi siswa & bimbingan halaqah.</p></div>
                    <div class="border border-amber-200 bg-amber-50/50 rounded-xl p-4"><div class="font-semibold text-amber-800 text-sm">Siswa & Karyawan (Role 2 & 4)</div><p class="text-xs text-gray-600 mt-1">Melakukan presensi RFID/QR Code, mengikuti ujian, cek tagihan spp, serta dompet saldo topup.</p></div>
                </div>
            </div>
        </div>

        <!-- TAB 2: PENGGUNA & AKUN -->
        <div x-show="activeTab === 'users' && matchesSearch('pengguna akun user murid siswa guru karyawan jabatan password status')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Manajemen Akun & Pengguna</h2>
                <p class="text-xs sm:text-sm text-gray-500">Panduan pengelolaan data Murid, Guru, Karyawan, dan Akun Pengguna</p>
            </div>
            <div class="space-y-4 text-sm text-gray-600">
                <div class="border-l-4 border-blue-500 pl-4 py-1"><h3 class="font-semibold text-gray-800">1. Kelola Akun Pengguna (<code>/dashboard/master/akun</code>)</h3><p class="mt-1">Halaman ini menampilkan <strong>semua akun pengguna</strong> dalam sistem (Admin, Guru, Siswa, Karyawan). Anda dapat memfilter pengguna berdasarkan <strong>Tipe Account</strong> maupun <strong>Jabatan</strong>, melakukan <strong>Edit Password</strong> instan, serta mengubah <strong>Status Aktif/Nonaktif</strong> akun.</p></div>
                <div class="border-l-4 border-blue-500 pl-4 py-1"><h3 class="font-semibold text-gray-800">2. Pendaftaran Data Murid / Mahasiswa</h3><p class="mt-1">Dapat ditambahkan secara manual melalui menu <code>Master &gt; Murid</code> (lihat tab <strong>Tambah Murid</strong>) atau secara masal mengunduh file template Excel/CSV yang telah disediakan kemudian mengunggahnya melalui tombol <strong>Import</strong>.</p></div>
                <div class="border-l-4 border-blue-500 pl-4 py-1"><h3 class="font-semibold text-gray-800">3. Pendaftaran Karyawan & Jabatan</h3><p class="mt-1">Jabatan karyawan seperti <em>Kepala Sekolah, Bendahara, Wali Kelas, Staf IT</em> dikelola pada menu <code>Master &gt; Jabatan</code>. Saat menambahkan Karyawan baru, akun pengguna otomatis dibuat dan terhubung dengan Jabatan yang dipilih.</p></div>
            </div>
        </div>

        <!-- TAB: TAMBAH DATA MURID -->
        <div x-show="activeTab === 'student' && matchesSearch('tambah murid siswa data nis nama kelas semester orang tua wali simpan import')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Cara Menambah Data Murid</h2>
                <p class="text-xs sm:text-sm text-gray-500">Langkah demi langkah menambah satu murid baru melalui menu Master &gt; Murid</p>
            </div>
            <div class="space-y-6 text-sm text-gray-600">

                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">1</span>Buka menu Murid</h3>
                    <p class="mt-1">Di Dashboard, gulir ke bagian <strong>Master</strong> lalu klik kartu <strong>Murid</strong>.</p>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Dashboard Breskul" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">2</span>Klik tombol Tambah</h3>
                    <p class="mt-1">Klik tombol hijau <strong>Tambah</strong> di atas tabel. Tombol <strong>Import</strong> di sebelahnya dipakai untuk memasukkan banyak data sekaligus.</p>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Halaman daftar murid" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">3</span>Isi NIS dan Nama</h3>
                    <p class="mt-1">Ketik nomor induk di kolom <strong>NIS</strong> (contoh: 00005), lalu nama lengkap di kolom <strong>Nama</strong> (contoh: Muhammad Fulan).</p>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Formulir tambah murid kosong" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">4</span>Pilih Kelas dan Semester</h3>
                    <p class="mt-1">Pilih <strong>Kelas</strong> (contoh: VII) dan <strong>Semester</strong> (contoh: 2026/2027), lalu isi <strong>Alamat</strong>.</p>
                    <div class="mt-2 rounded-lg bg-amber-50 border border-amber-200 text-amber-900 p-3 text-xs">Jika pilihan kosong, buat dulu datanya di <code>Master &gt; Kelas</code> dan <code>Master &gt; Semester</code>.</div>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Kelas dan semester terpilih" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">5</span>Lengkapi data pribadi</h3>
                    <ul class="mt-1 list-disc pl-5 space-y-1">
                        <li><strong>Jenis Kelamin:</strong> Laki-laki atau Perempuan.</li>
                        <li><strong>Keterangan Pesantren:</strong> Bukan Pesantren atau Pesantren.</li>
                        <li><strong>Photo:</strong> opsional, klik <em>Choose File</em> untuk mengunggah.</li>
                        <li><strong>Tempat, Tanggal lahir:</strong> ketik tempat (contoh: Brebes), pilih tanggal format bulan/hari/tahun.</li>
                        <li><strong>Nomor HP</strong> dan <strong>Email</strong> murid.</li>
                    </ul>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Data pribadi terisi" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">6</span>Isi Data Orang Tua/Wali</h3>
                    <p class="mt-1">Gulir ke bawah. Isi <strong>Nama</strong> dan <strong>Pekerjaan</strong> Ayah dan Ibu, lalu <strong>Nomor HP Orang Tua</strong>.</p>
                    <img class="mt-3 w-full rounded-lg border border-gray-200" alt="Data orang tua terisi" src="data:image/webp;base64,">
                </div>
                <div class="border-l-4 border-green-500 pl-4 py-1">
                    <h3 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs">7</span>Periksa lalu klik Simpan</h3>
                    <p class="mt-1">Pastikan NIS, nama, kelas, semester, dan tanggal lahir sudah benar. Klik tombol hijau <strong>Simpan</strong> di kiri bawah formulir, lalu klik <strong>Kembali</strong> dan cek apakah nama murid sudah muncul di tabel Murid.</p>
                </div>
                <div class="rounded-xl bg-blue-50 border border-blue-200 text-blue-900 p-4 text-xs"><strong>Catatan:</strong> kotak gelap berisi saran nama, alamat, atau nomor HP yang kadang muncul saat mengetik berasal dari isian otomatis browser, bukan dari Breskul.</div>
            </div>
        </div>

        <!-- TAB: PEMBAYARAN (MASTER & OPERASIONAL) -->
        <div x-show="activeTab === 'payment' && matchesSearch('pembayaran master tagihan verifikasi spp nominal jatuh tempo auto renew kas operasional')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-8" x-transition>
            
            <!-- HEADER -->
            <div class="border-b border-gray-100 pb-4">
                <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-green-100 text-green-800 text-xs font-semibold uppercase tracking-wider mb-2">Panduan Input & CRUD</div>
                <h2 class="text-xl sm:text-2xl font-bold text-gray-800">Panduan Pembayaran (Master & Verifikasi Operasional)</h2>
                <p class="text-xs sm:text-sm text-gray-500">Petunjuk langkah demi langkah input Master Pembayaran dan proses Verifikasi Pembayaran di menu Operasional</p>
            </div>

            <!-- BAGIAN 1: MASTER PEMBAYARAN -->
            <div class="space-y-4">
                <div class="flex items-center gap-2 pb-2 border-b border-gray-200">
                    <span class="p-2 rounded-lg bg-green-500 text-white font-bold text-sm">1</span>
                    <div>
                        <h3 class="font-bold text-gray-800 text-base sm:text-lg">Tambah Master Pembayaran</h3>
                        <p class="text-xs text-gray-500">Lokasi menu: <code>Master &gt; Pembayaran</code> (URL: <code>/dashboard/master/pembayaran</code>)</p>
                    </div>
                </div>

                <div class="space-y-4 text-sm text-gray-600">
                    <div class="border-l-4 border-green-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs font-bold">1</span>Buka Menu Master Pembayaran</h4>
                        <p class="mt-1">Pada Dashboard, gulir ke bagian <strong>Master</strong> lalu klik menu <strong>Pembayaran</strong>.</p>
                    </div>

                    <div class="border-l-4 border-green-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs font-bold">2</span>Klik Tombol Tambah</h4>
                        <p class="mt-1">Klik tombol hijau <strong>Tambah</strong> di pojok kanan atas tabel.</p>
                    </div>

                    <div class="border-l-4 border-green-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs font-bold">3</span>Isi Formulir Input Pembayaran</h4>
                        <div class="mt-2 space-y-2 bg-gray-50 rounded-xl p-4 border border-gray-200 text-xs sm:text-sm">
                            <div class="grid grid-cols-1 md:grid-cols-4 gap-2 py-1 border-b border-gray-200">
                                <span class="font-semibold text-gray-800">Nama <span class="text-red-500">*</span></span>
                                <span class="md:col-span-3 text-gray-600">Ketik nama jenis pembayaran (contoh: <code>SPP Bulanan</code>, <code>Biaya Ujian</code>, <code>Uang Gedung</code>).</span>
                            </div>
                            <div class="grid grid-cols-1 md:grid-cols-4 gap-2 py-1 border-b border-gray-200">
                                <span class="font-semibold text-gray-800">Nominal <span class="text-red-500">*</span></span>
                                <span class="md:col-span-3 text-gray-600">Ketik nominal biaya (contoh: <code>250000</code>). Input otomatis terformat rupiah (Rp 250.000).</span>
                            </div>
                            <div class="grid grid-cols-1 md:grid-cols-4 gap-2 py-1 border-b border-gray-200">
                                <span class="font-semibold text-gray-800">Tanggal Jatuh Tempo</span>
                                <span class="md:col-span-3 text-gray-600">Pilih tanggal batas waktu pembayaran (opsional).</span>
                            </div>
                            <div class="grid grid-cols-1 md:grid-cols-4 gap-2 py-1">
                                <span class="font-semibold text-gray-800">Auto Renew</span>
                                <span class="md:col-span-3 text-gray-600">Centang kotak <strong>"Generate otomatis perbulan (Auto Renew)"</strong> jika tagihan berulang setiap bulan. Tanggal jatuh tempo akan diterapkan pada bulan berjalan.</span>
                            </div>
                        </div>
                    </div>

                    <div class="border-l-4 border-green-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-green-600 text-white text-xs font-bold">4</span>Simpan Data & Aksi Tabel (Edit / Hapus)</h4>
                        <p class="mt-1">Klik tombol <strong>Simpan</strong>. Data baru langsung tersimpan dan muncul pada tabel.</p>
                        <ul class="mt-2 list-disc list-inside text-xs text-gray-500 space-y-1">
                            <li><strong>Edit:</strong> Klik ikon pensil hijau untuk mengubah nama, nominal, atau tanggal jatuh tempo.</li>
                            <li><strong>Hapus:</strong> Klik ikon tempat sampah merah untuk menghapus jenis pembayaran.</li>
                        </ul>
                    </div>
                </div>
            </div>

            <!-- BAGIAN 2: VERIFIKASI PEMBAYARAN DI MENU OPERASIONAL -->
            <div class="space-y-4 pt-4 border-t border-gray-200">
                <div class="flex items-center gap-2 pb-2 border-b border-gray-200">
                    <span class="p-2 rounded-lg bg-blue-500 text-white font-bold text-sm">2</span>
                    <div>
                        <h3 class="font-bold text-gray-800 text-base sm:text-lg">Verifikasi Pembayaran & Assign Tagihan di Menu Operasional</h3>
                        <p class="text-xs text-gray-500">Lokasi menu: <code>Operasional / Keuangan &gt; Pembayaran</code> (URL: <code>/dashboard/pembayaran</code>)</p>
                    </div>
                </div>

                <div class="space-y-4 text-sm text-gray-600">
                    <div class="border-l-4 border-blue-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-blue-600 text-white text-xs font-bold">1</span>Buka Menu Pembayaran</h4>
                        <p class="mt-1">Pada Dashboard, buka menu <strong>Keuangan &gt; Pembayaran</strong> (atau Operasional).</p>
                    </div>

                    <div class="border-l-4 border-blue-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-blue-600 text-white text-xs font-bold">2</span>Cari Data Murid</h4>
                        <p class="mt-1">Ketik NIS atau Nama pada kotak pencarian, atau gunakan filter <strong>Kelas / Prodi</strong> dan filter <strong>Bulan</strong>.</p>
                    </div>

                    <div class="border-l-4 border-blue-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-blue-600 text-white text-xs font-bold">3</span>Klik Tombol "Verifikasi"</h4>
                        <p class="mt-1">Pada kolom <strong>Data Tagihan & Pembayaran</strong>, cari tagihan yang berstatus <span class="px-2 py-0.5 rounded text-xs font-semibold bg-amber-100 text-amber-700">Tagihan</span>, lalu klik tombol hijau <strong>Verifikasi</strong>.</p>
                    </div>

                    <div class="border-l-4 border-blue-500 pl-4 py-1">
                        <h4 class="font-semibold text-gray-800"><span class="inline-flex w-6 h-6 mr-2 items-center justify-center rounded-full bg-blue-600 text-white text-xs font-bold">4</span>Konfirmasi Verifikasi</h4>
                        <p class="mt-1">Pada dialog pop-up <em>"Verifikasi Pembayaran?"</em>, klik tombol <strong>Ya, Verifikasi!</strong>.</p>
                        <div class="mt-2 p-3 bg-blue-50 border border-blue-200 rounded-xl text-xs text-blue-900 space-y-1">
                            <p><strong>Hasil setelah verifikasi:</strong></p>
                            <p>✓ Status tagihan otomatis berubah menjadi <span class="px-1.5 py-0.5 rounded font-semibold bg-green-100 text-green-700">Lunas</span>.</p>
                            <p>✓ Transaksi pemasukan otomatis tercatat pada <strong>Buku Kas</strong>.</p>
                            <p>✓ Notifikasi push dikirimkan ke aplikasi mobile siswa/wali murid.</p>
                        </div>
                    </div>

                    <!-- Tambahan: Input Tagihan ke Murid -->
                    <div class="border-l-4 border-purple-500 pl-4 py-1 bg-purple-50/40 rounded-r-xl p-3">
                        <h4 class="font-semibold text-gray-800 flex items-center gap-1.5">
                            <span class="inline-flex w-6 h-6 items-center justify-center rounded-full bg-purple-600 text-white text-xs font-bold">+</span>
                            Cara Tambah / Assign Tagihan ke Murid:
                        </h4>
                        <ol class="mt-2 list-decimal list-inside space-y-1 text-xs text-gray-700">
                            <li>Centang kotak (checkbox) pada nama murid yang ingin ditagihkan (atau klik tombol <strong>Pilih Semua</strong>).</li>
                            <li>Klik tombol biru <strong>+ Tambah Pembayaran</strong> di kanan atas tabel.</li>
                            <li>Pilih jenis pembayaran pada dropdown modal pop-up, lalu klik <strong>Simpan</strong>.</li>
                        </ol>
                    </div>
                </div>
            </div>

        </div>

        <!-- TAB 3: ABSENSI -->
        <div x-show="activeTab === 'attendance' && matchesSearch('absensi presensi rfid qrcode scan jam masuk pulang denda')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Presensi & Integrasi RFID / QR Code</h2>
                <p class="text-xs sm:text-sm text-gray-500">Pengaturan jadwal kehadiran, toleransi keterlambatan, dan riwayat presensi</p>
            </div>
            <div class="space-y-4 text-sm text-gray-600">
                <div class="bg-emerald-50 rounded-xl p-4 border border-emerald-200">
                    <h4 class="font-bold text-emerald-800">Langkah Pengaturan Absensi:</h4>
                    <ol class="list-decimal list-inside space-y-1.5 mt-2 text-emerald-900">
                        <li>Buka menu <code>Master &gt; Setting Absensi</code> untuk menetapkan waktu <strong>Jam Masuk</strong> dan <strong>Jam Pulang</strong> per Jabatan/Role.</li>
                        <li>Tentukan batas toleransi keterlambatan (dalam menit) serta besaran nominal denda keterlambatan jika diberlakukan.</li>
                        <li>Pastikan nomor Kartu RFID atau QR Code siswa sudah terdaftar melalui tombol <strong>Scan RFID</strong> pada data murid.</li>
                    </ol>
                </div>
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
                    <div class="border rounded-xl p-4"><h4 class="font-semibold text-gray-800 mb-1">Presensi Masuk & Pulang</h4><p class="text-xs text-gray-500">Siswa/Karyawan melakukan tempel kartu RFID pada mesin scanner yang terhubung ke Web Service API. Status otomatis tercatat Masuk/Terlambat.</p></div>
                    <div class="border rounded-xl p-4"><h4 class="font-semibold text-gray-800 mb-1">Monitoring & Laporan</h4><p class="text-xs text-gray-500">Admin/Guru dapat memantau kehadiran secara real-time pada menu <code>Operasional &gt; Absensi</code> lengkap dengan filter tanggal dan peran.</p></div>
                </div>
            </div>
        </div>

        <!-- TAB 4: KEUANGAN -->
        <div x-show="activeTab === 'finance' && matchesSearch('keuangan pembayaran spp tagihan saldo topup kas midtrans verifikasi')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Keuangan, Tagihan SPP & Buku Kas</h2>
                <p class="text-xs sm:text-sm text-gray-500">Pengelolaan modul pembayaran, transaksi online Midtrans, dompet saldo, dan kas</p>
            </div>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-6 text-sm text-gray-600">
                <div class="space-y-3 border rounded-2xl p-5">
                    <h3 class="font-bold text-gray-800 text-base">💳 Tagihan & Pembayaran SPP</h3>
                    <ul class="space-y-2 text-xs sm:text-sm">
                        <li>• <strong>Master Jenis Pembayaran:</strong> Dibuat di <code>Master &gt; Pembayaran</code>. <button type="button" @click="activeTab = 'payment'" class="text-green-600 hover:underline font-semibold cursor-pointer">Buka Panduan CRUD &rarr;</button></li>
                        <li>• <strong>Assign & Verifikasi:</strong> Buka <code>Keuangan &gt; Pembayaran</code> untuk input tagihan dan verifikasi pembayaran. <button type="button" @click="activeTab = 'payment'" class="text-green-600 hover:underline font-semibold cursor-pointer">Buka Panduan CRUD &rarr;</button></li>
                    </ul>
                </div>
                <div class="space-y-3 border rounded-2xl p-5">
                    <h3 class="font-bold text-gray-800 text-base">👛 Saldo, Topup & Buku Kas</h3>
                    <ul class="space-y-2 text-xs sm:text-sm">
                        <li>• <strong>Dompet Saldo Siswa:</strong> Digunakan untuk transaksi di kantin/internal sekolah. Pengisian saldo dikelola pada menu <code>Keuangan &gt; Topup</code>.</li>
                        <li>• <strong>Buku Kas Instansi:</strong> Perekaman transaksi Pemasukan & Pengeluaran secara transparan di menu <code>Keuangan &gt; Kas</code>.</li>
                    </ul>
                </div>
            </div>
        </div>

        <!-- TAB 5: AKADEMIK -->
        <div x-show="activeTab === 'academic' && matchesSearch('akademik ujian bank soal kelas prodi mapel halaqah pdf')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Akademik & Ujian Online</h2>
                <p class="text-xs sm:text-sm text-gray-500">Pengelolaan struktur kelas/prodi, bank soal, jadwal ujian, dan cetak PDF</p>
            </div>
            <div class="space-y-4 text-sm text-gray-600">
                <div class="border-l-4 border-amber-500 pl-4 py-1"><h3 class="font-semibold text-gray-800">1. Bank Soal & Pembuatan Soal</h3><p class="mt-1">Guru/Dosen menginput paket soal pada menu <code>Ujian &gt; Soal</code>. Dapat diinput manual lengkap dengan bobot nilai/kunci jawaban atau melalui fitur <strong>Import Excel Soal</strong>.</p></div>
                <div class="border-l-4 border-amber-500 pl-4 py-1"><h3 class="font-semibold text-gray-800">2. Pelaksanaan & Penjadwalan Ujian</h3><p class="mt-1">Setelah soal siap, Guru mengaktifkan ujian pada menu <code>Ujian &gt; Ujian</code>. Jadwal sesi dan penugasan kelas diatur agar siswa dapat mengerjakan langsung dari aplikasi web/mobile. Berita acara dapat diunduh dalam format <strong>PDF</strong>.</p></div>
            </div>
        </div>

        <!-- TAB 6: MOBILE -->
        <div x-show="activeTab === 'mobile' && matchesSearch('mobile flutter breskul_app android notifikasi fcm siswa orang tua')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Aplikasi Mobile Breskul (breskul_app)</h2>
                <p class="text-xs sm:text-sm text-gray-500">Panduan penggunaan aplikasi Flutter untuk Siswa, Mahasiswa, dan Orang Tua</p>
            </div>
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs sm:text-sm text-gray-600">
                <div class="p-4 border rounded-xl bg-indigo-50/40"><div class="font-bold text-indigo-900 mb-1">🔔 Notifikasi Push FCM</div><p>Siswa & Ortu menerima notifikasi instan saat ada pengumuman baru, tagihan SPP terbit, atau konfirmasi pembayaran lunas.</p></div>
                <div class="p-4 border rounded-xl bg-indigo-50/40"><div class="font-bold text-indigo-900 mb-1">📲 Scan Presensi & Saldo</div><p>Memeriksa riwayat kehadiran harian, sisa saldo dompet sekolah, serta pembayaran langsung via Midtrans Snap Gateway.</p></div>
                <div class="p-4 border rounded-xl bg-indigo-50/40"><div class="font-bold text-indigo-900 mb-1">📝 Ujian Mobile</div><p>Siswa dapat mengerjakan ujian secara langsung lewat handphone dengan tampilan antarmuka yang ramah dan responsif.</p></div>
            </div>
        </div>

        <!-- TAB 7: FAQ -->
        <div x-show="activeTab === 'faq' && matchesSearch('faq kendala error lupa password rfid tidak terbaca pertanyaaan umum')" class="bg-white rounded-2xl shadow-md p-6 sm:p-8 space-y-6" x-transition>
            <div class="border-b border-gray-100 pb-4">
                <h2 class="text-xl font-bold text-gray-800">Pertanyaan Umum (FAQ) & Problem Solving</h2>
                <p class="text-xs sm:text-sm text-gray-500">Solusi cepat untuk kendala teknis yang sering ditemui</p>
            </div>
            <div class="space-y-4">
                <template x-for="(item, index) in faqs" :key="index">
                    <div class="border border-gray-200 rounded-xl overflow-hidden">
                        <button @click="item.open = !item.open" class="w-full px-5 py-4 text-left font-semibold text-gray-800 hover:bg-gray-50 flex items-center justify-between transition-colors text-sm sm:text-base">
                            <span x-text="item.question"></span>
                            <svg xmlns="http://www.w3.org/2000/svg" class="w-5 h-5 text-gray-400 transition-transform duration-200" :class="item.open ? 'rotate-180' : ''" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
                        </button>
                        <div x-show="item.open" class="px-5 pb-4 text-xs sm:text-sm text-gray-600 bg-gray-50/50 border-t border-gray-100 pt-3" x-transition><p x-text="item.answer"></p></div>
                    </div>
                </template>
            </div>
        </div>

        <!-- Bottom Tab Navigation (Pindah Tab di Bawah Konten) -->
        <div class="flex items-center justify-between gap-3 pt-4 border-t border-gray-200 bg-white p-4 rounded-2xl shadow-sm">
            <button type="button" @click="prevTab()" :disabled="!getPrevTab()"
                class="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl border border-gray-300 bg-white hover:bg-gray-50 text-gray-700 text-xs sm:text-sm font-semibold shadow-xs transition disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">
                <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" />
                </svg>
                <span>&larr; <span x-text="getPrevTab() ? getPrevTab().label : 'Sebelumnya'"></span></span>
            </button>

            <span class="text-xs text-gray-400 font-medium hidden sm:inline">
                Topik <span class="font-bold text-gray-700" x-text="getCurrentTabIndex() + 1"></span> dari <span x-text="tabs.length"></span>
            </span>

            <button type="button" @click="nextTab()" :disabled="!getNextTab()"
                class="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-green-600 hover:bg-green-700 text-white text-xs sm:text-sm font-semibold shadow-xs transition disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">
                <span><span x-text="getNextTab() ? getNextTab().label : 'Selanjutnya'"></span> &rarr;</span>
                <svg xmlns="http://www.w3.org/2000/svg" class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7" />
                </svg>
            </button>
        </div>

    </div>
</div>
</main>

<script>
function panduanApp() {
    return {
        searchQuery: '',
        activeTab: 'overview',
        tabs: [
            { id: 'overview', label: 'Pengenalan', icon: 'ℹ️' },
            { id: 'users', label: 'Pengguna & Akun', icon: '👥' },
            { id: 'student', label: 'Tambah Murid', icon: '🎓' },
            { id: 'payment', label: 'Pembayaran', icon: '💳' },
            { id: 'attendance', label: 'Presensi & RFID', icon: '⏰' },
            { id: 'finance', label: 'Keuangan & Kas', icon: '💰' },
            { id: 'academic', label: 'Akademik & Ujian', icon: '📚' },
            { id: 'mobile', label: 'Aplikasi Mobile', icon: '📱' },
            { id: 'faq', label: 'FAQ & Kendala', icon: '❓' }
        ],
        faqs: [
            { question: "Bagaimana cara mereset password akun pengguna yang lupa?", answer: "Admin dapat membuka menu Master > Akun, cari nama/username pengguna, lalu klik tombol 'Edit Password'. Masukkan password baru (minimal 6 karakter) dan simpan.", open: true },
            { question: "Mengapa kartu RFID siswa tidak merespon saat di-scan?", answer: "Pastikan nomor kartu RFID siswa sudah dimasukkan pada data murid (Master > Murid > Edit/Scan RFID). Jika belum terdaftar, sistem tidak akan mengenali ID kartu saat scanner membaca kartu.", open: false },
            { question: "Bagaimana cara melakukan konfirmasi pembayaran manual?", answer: "Buka menu Keuangan > Pembayaran. Cari siswa yang bersangkutan, lalu klik Verifikasi pada daftar tagihan. Pembayaran akan otomatis ditandai Lunas dan dicatat di Buku Kas.", open: false },
            { question: "Bagaimana cara mengunggah soal ujian secara masal?", answer: "Masuk ke menu Ujian > Soal, klik tombol 'Template Excel' untuk mengunduh format excel yang sesuai. Isi soal dan pilihan jawaban, kemudian unggah melalui tombol 'Import Soal'.", open: false }
        ],
        matchesSearch(keywords) {
            if (!this.searchQuery.trim()) return true;
            return keywords.toLowerCase().includes(this.searchQuery.toLowerCase());
        },
        getCurrentTabIndex() {
            return this.tabs.findIndex(t => t.id === this.activeTab);
        },
        getPrevTab() {
            const idx = this.getCurrentTabIndex();
            return idx > 0 ? this.tabs[idx - 1] : null;
        },
        getNextTab() {
            const idx = this.getCurrentTabIndex();
            return idx >= 0 && idx < this.tabs.length - 1 ? this.tabs[idx + 1] : null;
        },
        goToTab(tabId) {
            this.activeTab = tabId;
            this.$nextTick(() => {
                const btn = document.getElementById('tab-btn-' + tabId);
                if (btn) {
                    btn.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
                }
            });
        },
        prevTab() {
            const prev = this.getPrevTab();
            if (prev) {
                this.goToTab(prev.id);
                window.scrollTo({ top: 120, behavior: 'smooth' });
            }
        },
        nextTab() {
            const next = this.getNextTab();
            if (next) {
                this.goToTab(next.id);
                window.scrollTo({ top: 120, behavior: 'smooth' });
            }
        },
        scrollTabs(direction) {
            const container = this.$refs.tabContainer;
            if (container) {
                const amount = direction === 'left' ? -250 : 250;
                container.scrollBy({ left: amount, behavior: 'smooth' });
            }
        }
    }
}
</script>
</body>
</html>